import numpy as np
from collections import defaultdict

def generate_valid_triplets():
    """Generate all nonnegative integer triplets summing to 30 with |xi - xj| = 6 for some i,j"""
    triplets = []
    for x in range(0, 31):
        for y in range(0, 31 - x):
            z = 30 - x - y
            # Check if any pair has absolute difference of 6
            if abs(x - y) == 6 or abs(x - z) == 6 or abs(y - z) == 6:
                triplets.append((x, y, z))
    return triplets

def calculate_guaranteed_winnings(guess_triplet, valid_triplets):
    """Calculate minimum winnings over all valid triplets and all permutations"""
    min_winnings = float('inf')

    for triplet in valid_triplets:
        # Generate all permutations of the triplet
        permutations = list(itertools.permutations(triplet))

        for perm in permutations:
            winnings = 0
            for i in range(3):
                if guess_triplet[i] <= perm[i]:
                    winnings += guess_triplet[i]

            if winnings < min_winnings:
                min_winnings = winnings

    return min_winnings

def main():
    # Generate all valid triplets
    valid_triplets = generate_valid_triplets()
    print(f"Number of valid triplets: {len(valid_triplets)}")

    # Generate all possible guess triplets (0-30 inclusive)
    # This would be 31^3 = 29,791 possibilities
    max_guaranteed = -1
    optimal_guesses = []

    # We'll optimize by considering that guesses might be non-decreasing without loss of generality
    # Since Bob's strategy should be symmetric and we want to reduce computation
    guess_values = range(0, 31)

    count = 0
    for g1 in guess_values:
        for g2 in guess_values:
            for g3 in guess_values:
                guess = (g1, g2, g3)
                guaranteed = calculate_guaranteed_winnings(guess, valid_triplets)

                if guaranteed > max_guaranteed:
                    max_guaranteed = guaranteed
                    optimal_guesses = [guess]
                elif guaranteed == max_guaranteed:
                    optimal_guesses.append(guess)

                count += 1
                if count % 10000 == 0:
                    print(f"Processed {count} guess combinations...")

    print(f"\nMaximum guaranteed coins: {max_guaranteed}")
    print(f"Maximum guaranteed money (×1000): {max_guaranteed * 1000}")
    print(f"\nNumber of optimal guess triplets: {len(optimal_guesses)}")
    print("\nFirst 10 optimal guess triplets (g1, g2, g3):")
    for i, guess in enumerate(optimal_guesses[:10]):
        print(f"  {guess}")

    # Also show some symmetric properties
    print("\nNote: Since the host permutes randomly, any permutation of an optimal guess is also optimal.")
    print("Showing only unique ordered triples (non-decreasing):")
    unique_ordered = set()
    for guess in optimal_guesses:
        unique_ordered.add(tuple(sorted(guess)))

    for guess in sorted(unique_ordered):
        print(f"  {guess}")

if __name__ == "__main__":
    main()"}

